-- loan_disbursement: A disbursement (single or tranche) of loan funds
CREATE TABLE loan_disbursement (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  loan_id                      uuid NOT NULL REFERENCES loan(id),
  tranche_no                   integer NOT NULL DEFAULT 1,
  amount                       numeric(28,8) NOT NULL,
  fees_deducted                numeric(28,8) NOT NULL DEFAULT 0,
  net_amount                   numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  method                       varchar(40) NOT NULL CHECK (method IN ('DEPOSIT_ACCOUNT', 'WALLET', 'EXTERNAL_TRANSFER', 'MERCHANT_SETTLEMENT', 'CASH', 'CARD')),
  destination_account_id       uuid,
  destination_wallet_id        uuid,
  merchant_id                  uuid,
  payment_id                   uuid,
  scheduled_date               date,
  status                       varchar(40) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('SCHEDULED', 'PENDING', 'COMPLETED', 'FAILED', 'REVERSED', 'CANCELLED')),
  journal_entry_id             uuid,
  disbursed_at                 timestamptz,
  failure_reason               varchar(255),
  attempts                     integer NOT NULL DEFAULT 1,
  idempotency_key              varchar(128) NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_loan_disbursement_1 UNIQUE (tenant_id, idempotency_key)
);
