  loan_id                      uuid NOT NULL REFERENCES loan(id),
  restructure_type             varchar(40) NOT NULL CHECK (restructure_type IN ('RESCHEDULE', 'REFINANCE', 'PAYMENT_HOLIDAY', 'TERM_EXTENSION', 'RATE_REDUCTION', 'CAPITALISATION', 'SETTLEMENT')),
  status                       varchar(40) NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'APPLIED', 'CANCELLED')),
  reason                       varchar(500) NOT NULL,
