CREATE INDEX ix_bnpl_plan_product_version_id ON bnpl_plan (product_version_id);
CREATE INDEX ix_bnpl_plan_legal_entity_id ON bnpl_plan (legal_entity_id);
CREATE INDEX ix_bnpl_plan_merchant_settlement_account_id ON bnpl_plan (merchant_settlement_account_id);
CREATE INDEX ix_bnpl_plan_repayment_account_id ON bnpl_plan (repayment_account_id);
ALTER TABLE bnpl_plan ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON bnpl_plan USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_bnpl_plan_touch BEFORE UPDATE ON bnpl_plan FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA loan TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA loan TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA loan GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
